// RestorePersisted is the single production hydration path used by the
// Data Engine aggregate repository. Migration and tracker restoration happen
// before the DAO is published through its entity.
func (d *WorldDao) RestorePersisted(raw []byte, schemaVersion uint32, version uint64) error {
	if schemaVersion > WorldDaoSchemaVersion {
		return fmt.Errorf("dao WorldDao: stored schema %d is newer than runtime schema %d", schemaVersion, WorldDaoSchemaVersion)
	}
	var err error
	if schemaVersion < WorldDaoSchemaVersion {
		raw, err = d.Migrate(raw, schemaVersion)
		if err != nil {
			return fmt.Errorf("dao WorldDao: migrate schema %d to %d: %w", schemaVersion, WorldDaoSchemaVersion, err)
		}
	}
	if err := d.Unmarshal(raw); err != nil {
		return err
	}
	d.tracker.SetVersion(version)
	d.CleanDirty()
	return nil
}

